#include <cstdint>
#include <cstdlib>
#include <iostream>

struct Node {
    Node* left;
    Node* right;

    Node(Node* l = nullptr, Node* r = nullptr) : left(l), right(r) {}
};

static Node* makeTree(int depth) {
    if (depth == 0) {
        return new Node();
    }
    return new Node(makeTree(depth - 1), makeTree(depth - 1));
}

static std::uint64_t treeCheck(const Node* node) {
    if (node->left == nullptr) {
        return 1;
    }
    return 1 + treeCheck(node->left) + treeCheck(node->right);
}

static void deleteTree(Node* node) {
    if (node == nullptr) {
        return;
    }
    deleteTree(node->left);
    deleteTree(node->right);
    delete node;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        return 1;
    }

    const int n = std::atoi(argv[1]);

    Node* stretchTree = makeTree(n + 1);
    std::cout << "stretch tree of depth " << (n + 1)
              << "\t check: " << treeCheck(stretchTree) << '\n';
    deleteTree(stretchTree);

    Node* longLivedTree = makeTree(n);

    for (int depth = 4; depth <= n; depth += 2) {
        const std::uint64_t treeCount =
            std::uint64_t(1) << (n - depth + 4);

        std::uint64_t totalCheck = 0;
        for (std::uint64_t i = 0; i < treeCount; ++i) {
            Node* tree = makeTree(depth);
            totalCheck += treeCheck(tree);
            deleteTree(tree);
        }

        std::cout << treeCount << "\t trees of depth " << depth
                  << "\t check: " << totalCheck << '\n';
    }

    std::cout << "long lived tree of depth " << n
              << "\t check: " << treeCheck(longLivedTree) << '\n';
    deleteTree(longLivedTree);

    return 0;
}

